import json
data = json.load(open('/app/resources/treasury_bulletin_1982_03.json'))
# Get element 340 (the table with maturity schedule)
elem = data['document']['elements'][340]
content = elem.get('content')

# Parse the HTML table
from html.parser import HTMLParser
import re

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.rows = []
        self.current_row = []
        self.current_data = ''
        self.in_td = False
        self.in_th = False

    def handle_starttag(self, tag, attrs):
        if tag == 'tr':
            self.current_row = []
        elif tag in ('td', 'th'):
            self.in_td = True
            self.current_data = ''

    def handle_endtag(self, tag):
        if tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
        elif tag in ('td', 'th'):
            self.in_td = False
            self.current_row.append(self.current_data.strip())

    def handle_data(self, data):
        if self.in_td:
            self.current_data += data

parser = TableParser()
parser.feed(content)

# Print first few rows to see structure
for i, row in enumerate(parser.rows[:5]):
    print(f'Row {i}: {row[:6]}')  # First 6 columns
